export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0;
  let baseDx = 0, baseDz = 0, baseCount = 0;
  let uLag = 0.45, lastThrust = 0.45;
  let intYaw = 0;

  let gateIdx = -1;
  let mode = 'approach';
  let alignCount = 0;
  let padSettled = false;

  return {
    step(obs) {
      const dt = 0.01;
      const op = obs.pos, ov = obs.vel, oa = obs.att, orates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = op.x; py = op.y; pz = op.z;
        vx = ov.x; vy = ov.y; vz = ov.z;
      }

      // Update motor lag estimate (nominal 40ms lag)
      uLag += (lastThrust - uLag) * (1 - Math.exp(-dt / 0.04));

      // Compute thrust direction from current attitude
      const cRoll = Math.cos(oa.roll), sRoll = Math.sin(oa.roll);
      const cPitch = Math.cos(oa.pitch), sPitch = Math.sin(oa.pitch);
      const cYaw = Math.cos(oa.yaw), sYaw = Math.sin(oa.yaw);

      const bodyX = sPitch * cRoll;
      const bodyZ = -sRoll;
      const dirX = cYaw * bodyX + sYaw * bodyZ;
      const dirY = cPitch * cRoll;
      const dirZ = -sYaw * bodyX + cYaw * bodyZ;

      const nomMass = 0.725;
      const dragCoeff = 0.42 / nomMass;
      const aThrustNom = (16.0 / nomMass) * uLag;

      // Predict velocity and update disturbance observer when airborne
      const airborne = op.y > 0.085;
      if (airborne) {
        const predVx = vx + (aThrustNom * dirX - dragCoeff * vx + dx) * dt;
        const predVy = vy + (aThrustNom * dirY - 9.81 - dragCoeff * vy + dy) * dt;
        const predVz = vz + (aThrustNom * dirZ - dragCoeff * vz + dz) * dt;

        const evx = ov.x - predVx;
        const evy = ov.y - predVy;
        const evz = ov.z - predVz;

        // Observer gains: fast velocity and disturbance tracking
        const bv = 0.42;
        const bdHoriz = 4.2;
        const bdVert = 2.8;

        vx = predVx + bv * evx;
        vy = predVy + bv * evy;
        vz = predVz + bv * evz;

        dx = clamp(dx + bdHoriz * evx, -6.5, 6.5);
        dy = clamp(dy + bdVert * evy, -5.5, 5.5);
        dz = clamp(dz + bdHoriz * evz, -6.5, 6.5);

        // During [0.45, 1.95] s, gusts have not started (gustStartMin = 2.0)
        if (obs.t >= 0.45 && obs.t <= 1.95) {
          baseCount++;
          const alpha = Math.max(0.04, 1 / baseCount);
          baseDx += alpha * (dx - baseDx);
          baseDz += alpha * (dz - baseDz);
        } else if (obs.t > 1.95 && baseCount > 10) {
          // Gentle decay of transient gust estimate toward learned base wind
          dx += (baseDx - dx) * 0.015;
          dz += (baseDz - dz) * 0.015;
        }
      } else {
        vx = ov.x; vy = ov.y; vz = ov.z;
      }

      // Position filter
      px = px + vx * dt + 0.65 * (op.x - (px + vx * dt));
      py = py + vy * dt + 0.65 * (op.y - (py + vy * dt));
      pz = pz + vz * dt + 0.65 * (op.z - (pz + vz * dt));

      // Actual acceleration currently produced by drone attitude + disturbance
      const effThrustAcc = Math.max(2.0, aThrustNom + dy / Math.max(0.7, dirY));
      const curAx = effThrustAcc * dirX - dragCoeff * vx + dx;
      const curAy = effThrustAcc * dirY - 9.81 - dragCoeff * vy;
      const curAz = effThrustAcc * dirZ - dragCoeff * vz + dz;

      let tx = px, ty = py, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          mode = 'approach';
          alignCount = 0;
        }

        // Always target the gate's Y and Z
        ty = g.y;
        tz = g.z;

        const errY = Math.abs(py - g.y);
        const errZ = Math.abs(pz - g.z);
        const tCross = clamp((g.x - px) / Math.max(0.35, vx), 0.05, 0.45);
        const predCrossY = py + vy * tCross + 0.5 * curAy * tCross * tCross;
        const predCrossZ = pz + vz * tCross + 0.5 * curAz * tCross * tCross;

        const alignedStrict =
          errZ < 0.052 &&
          errY < 0.095 &&
          Math.abs(predCrossZ - g.z) < 0.065 &&
          Math.abs(predCrossY - g.y) < 0.12 &&
          Math.abs(vz) < 0.18 &&
          Math.abs(vy) < 0.30;

        const alignedSafeToContinue =
          errZ < 0.085 &&
          errY < 0.15 &&
          Math.abs(predCrossZ - g.z) < 0.095 &&
          Math.abs(predCrossY - g.y) < 0.17;

        if (mode === 'approach') {
          const stageX = g.x - 0.28;
          tx = stageX;
          if (px > g.x - 0.55 && alignedStrict) {
            alignCount++;
            if (alignCount >= 4) {
              mode = 'cross';
            }
          } else {
            alignCount = Math.max(0, alignCount - 1);
          }
        }

        if (mode === 'cross') {
          // If still safely before the gate plane and a gust knocks us out of alignment, abort crossing
          if (px < g.x - 0.10 && !alignedSafeToContinue) {
            mode = 'approach';
            alignCount = 0;
            tx = g.x - 0.28;
            tvx = 0;
          } else {
            tx = g.x + 0.32;
            tvx = 0.65;
          }
        }
      } else {
        // Landing phase after Gate 2 (x = 1.35, y = 1.05, z = 1.05) -> Pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distH = Math.hypot(pad.x - px, pad.z - pz);
        const speedH = Math.hypot(vx, vz);

        if (!padSettled) {
          // Smooth glide slope down toward pad, holding at 0.22m until horizontally aligned
          ty = clamp(0.20 + 0.75 * distH, 0.20, 1.05);
          if (distH < 0.085 && speedH < 0.18 && py < 0.32) {
            padSettled = true;
          }
        }

        if (padSettled) {
          // If a strong gust pushes us outside landing radius while still airborne, pause descent
          if (py > 0.105 && distH > 0.125) {
            padSettled = false;
            ty = 0.22;
          } else {
            ty = 0.04;
            tvy = py > 0.11 ? -0.28 : -0.12;
          }
        }

        // Once touching down inside the pad radius with low speed, cut thrust & level attitude to lock landing
        if (py <= 0.082 && distH <= 0.115 && speedH < 0.25 && Math.abs(vy) < 0.25) {
          lastThrust = 0.02;
          return { thrust: 0.02, roll: 0, pitch: 0, yawRate: -2.0 * oa.yaw };
        }
      }

      // Lead-compensated velocity (incorporates current acceleration from attitude lag)
      const leadTau = 0.055;
      const vxLead = vx + leadTau * curAx;
      const vyLead = vy + 0.035 * curAy;
      const vzLead = vz + leadTau * curAz;

      // Position & Velocity PD gains
      const kpH = 5.6, kdH = 4.4;
      const ex = clamp(tx - px, -0.75, 0.75);
      const ez = clamp(tz - pz, -0.75, 0.75);

      const desAx = kpH * ex + kdH * (tvx - vxLead) + dragCoeff * vx - dx;
      const desAz = kpH * ez + kdH * (tvz - vzLead) + dragCoeff * vz - dz;

      const kpY = 7.5, kdY = 4.8;
      const ey = clamp(ty - py, -0.75, 0.75);
      const desAy = clamp(kpY * ey + kdY * (tvy - vyLead) + dragCoeff * vy - dy, -4.5, 5.5);

      // Desired total specific thrust acceleration
      const reqSpecificThrustY = Math.max(1.5, 9.81 + desAy);
      const tiltComp = Math.max(0.72, dirY);
      const totalAcc = reqSpecificThrustY / tiltComp;

      // Convert desired world (desAx, desAz) into body (bodyX, bodyZ) then (pitch, roll)
      const desDirX = clamp(desAx / totalAcc, -0.52, 0.52);
      const desDirZ = clamp(desAz / totalAcc, -0.52, 0.52);

      const desBodyX = cYaw * desDirX - sYaw * desDirZ;
      const desBodyZ = sYaw * desDirX + cYaw * desDirZ;

      const maxTilt = obs.gateIndex === 3 && py < 0.16 ? 0.16 : 0.48;
      const roll = clamp(- Math.asin(clamp(desBodyZ, -0.55, 0.55)), -maxTilt, maxTilt);
      const pitch = clamp(Math.asin(clamp(desBodyX / Math.max(0.8, Math.cos(roll)), -0.55, 0.55)), -maxTilt, maxTilt);

      const thrust = clamp((nomMass * totalAcc) / 16.0, 0.05, 1.0);
      lastThrust = thrust;

      intYaw = clamp(intYaw + oa.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.2 * oa.yaw - 1.5 * intYaw - 0.25 * orates.yaw, -2.0, 2.0);

      return { thrust, roll, pitch, yawRate };
    },
  };
}

